// WP-7.1 light tree on the GPU: see include/fuse/renderer/light_tree/light_tree_gpu.hpp.
#include <fuse/renderer/light_tree/light_tree_gpu.hpp>

#include <fuse/renderer/vk/allocator.hpp>
#include <fuse/renderer/vk/device.hpp>

#include <algorithm>
#include <cstring>

#if defined(FUSE_VULKAN_BACKEND)
#include <vulkan/vulkan.h>

// Generated by cmake/rp_wp71.cmake from shaders/light_tree/*: kLtSample<Slang|Glsl>Spv and
// FUSE_LIGHT_TREE_{SLANG,GLSL} when the kernel of a language exists.
#include "light_tree_spv.h"
#endif

namespace fuse::renderer::light_tree {

namespace {
constexpr u32 kPushBytes = sizeof(LightTreePush);

u64 align256(u64 v) { return (v + 255u) & ~u64{255u}; }

BufferUsage ringUsage() {
    return static_cast<BufferUsage>(static_cast<u32>(BufferUsage::Storage) |
                                    static_cast<u32>(BufferUsage::ShaderDeviceAddress) |
                                    static_cast<u32>(BufferUsage::TransferSrc));
}
} // namespace

LightTreeSlotLayout LightTreeSlotLayout::compute(u32 nodeCount, u32 emitterCount, u32 directionalCount) {
    LightTreeSlotLayout l{};
    u64 cursor = 0;
    auto take = [&](u64 bytes) {
        const u64 at = cursor;
        cursor = align256(cursor + std::max<u64>(bytes, 16u));
        return at;
    };
    l.header = take(sizeof(LightTreeHeader));
    l.nodes = take(static_cast<u64>(nodeCount) * sizeof(LightTreeNode));
    l.emitters = take(static_cast<u64>(emitterCount) * sizeof(LightTreeEmitter));
    l.directional = take(static_cast<u64>(directionalCount) * sizeof(u32));
    l.bytes = cursor;
    return l;
}

LightTreeCapabilities queryLightTreeCapabilities(const VulkanDevice* device) {
    LightTreeCapabilities c{};
#if defined(FUSE_VULKAN_BACKEND)
    if (device == nullptr || !device->isValid()) {
        return c;
    }
    const RendererCaps& caps = device->info().caps;
    if (!caps.bufferDeviceAddress || !caps.shaderInt64) {
        c.reason = "bufferDeviceAddress / shaderInt64 missing";
        return c;
    }
    c.gpu = true;
    c.reason = "ok";
#else
    (void)device;
    c.reason = "stub backend";
#endif
    return c;
}

LightTreeGpu::~LightTreeGpu() { destroy(); }

bool LightTreeGpu::init(const LightTreeGpuDesc& desc) {
    destroy();
    m_desc = desc;
#if defined(FUSE_VULKAN_BACKEND)
    if (desc.allocator == nullptr || desc.framesInFlight == 0u || desc.framesInFlight > kMaxSlots) {
        return false;
    }
    if (!queryLightTreeCapabilities(desc.device).gpu) {
        return false;
    }
    m_retired.reserve(8);
    m_initialized = true; // destroy() releases partial state from here on
    const u32 lights = std::max(desc.initialLights, 1u);
    const LightTreeSlotLayout sized = LightTreeSlotLayout::compute(2u * lights - 1u, lights, lights);
    if (!createPipeline() || !ensureCapacity(sized.bytes)) {
        destroy();
        return false;
    }
    return true;
#else
    return false;
#endif
}

void LightTreeGpu::destroy() {
    if (!m_initialized) {
        return;
    }
#if defined(FUSE_VULKAN_BACKEND)
    collectRetired(~0ull);
    if (m_ring.handle != nullptr) {
        m_desc.allocator->destroyBuffer(m_ring);
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    if (m_pipeline != nullptr) {
        vkDestroyPipeline(device, static_cast<VkPipeline>(m_pipeline), nullptr);
    }
    if (m_layoutHandle != nullptr) {
        vkDestroyPipelineLayout(device, static_cast<VkPipelineLayout>(m_layoutHandle), nullptr);
    }
#endif
    m_pipeline = nullptr;
    m_layoutHandle = nullptr;
    m_ring = Buffer{};
    m_ringQueue = rg::kNoQueue;
    m_slotStride = 0;
    m_slot = 0;
    for (u64& v : m_slotVersion) {
        v = 0u;
    }
    m_layout = LightTreeSlotLayout{};
    m_headerAddress = 0;
    m_retired.clear();
    m_recordCount = 0;
    m_language = "none";
    m_stats = LightTreeGpuStats{};
    m_initialized = false;
}

bool LightTreeGpu::createPipeline() {
#if defined(FUSE_VULKAN_BACKEND)
    const u32* words = nullptr;
    usize bytes = 0;
#if defined(FUSE_LIGHT_TREE_SLANG)
    if (m_desc.language == LightTreeKernelLanguage::Auto || m_desc.language == LightTreeKernelLanguage::Slang) {
        words = kLtSampleSlangSpv;
        bytes = sizeof(kLtSampleSlangSpv);
        m_language = "slang";
    }
#endif
#if defined(FUSE_LIGHT_TREE_GLSL)
    if (words == nullptr &&
        (m_desc.language == LightTreeKernelLanguage::Auto || m_desc.language == LightTreeKernelLanguage::Glsl)) {
        words = kLtSampleGlslSpv;
        bytes = sizeof(kLtSampleGlslSpv);
        m_language = "glsl";
    }
#endif
    if (words == nullptr) {
        return false;
    }
    const VkDevice device = static_cast<VkDevice>(m_desc.device->nativeHandle());
    VkDescriptorSetLayout setLayout =
        m_desc.bindless != nullptr ? static_cast<VkDescriptorSetLayout>(m_desc.bindless->layoutHandle()) : VK_NULL_HANDLE;
    VkPushConstantRange range{VK_SHADER_STAGE_COMPUTE_BIT, 0, kPushBytes};
    VkPipelineLayoutCreateInfo layoutInfo{};
    layoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
    layoutInfo.setLayoutCount = setLayout != VK_NULL_HANDLE ? 1u : 0u;
    layoutInfo.pSetLayouts = &setLayout;
    layoutInfo.pushConstantRangeCount = 1;
    layoutInfo.pPushConstantRanges = &range;
    VkPipelineLayout layout = VK_NULL_HANDLE;
    if (vkCreatePipelineLayout(device, &layoutInfo, nullptr, &layout) != VK_SUCCESS) {
        return false;
    }
    m_layoutHandle = layout;
    VkShaderModuleCreateInfo moduleInfo{};
    moduleInfo.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO;
    moduleInfo.codeSize = bytes;
    moduleInfo.pCode = words;
    VkShaderModule module = VK_NULL_HANDLE;
    if (vkCreateShaderModule(device, &moduleInfo, nullptr, &module) != VK_SUCCESS) {
        return false;
    }
    VkComputePipelineCreateInfo info{};
    info.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
    info.flags = m_desc.bindless != nullptr ? static_cast<VkPipelineCreateFlags>(m_desc.bindless->pipelineCreateFlags()) : 0u;
    info.stage.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO;
    info.stage.stage = VK_SHADER_STAGE_COMPUTE_BIT;
    info.stage.module = module;
    info.stage.pName = "main";
    info.layout = layout;
    VkPipeline pipeline = VK_NULL_HANDLE;
    const VkResult result = vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &info, nullptr, &pipeline);
    vkDestroyShaderModule(device, module, nullptr);
    m_pipeline = pipeline;
    return result == VK_SUCCESS;
#else
    return false;
#endif
}

bool LightTreeGpu::ensureCapacity(u64 slotBytes) {
    if (m_ring.handle != nullptr && slotBytes <= m_slotStride) {
        return true;
    }
    const u64 stride = align256(std::max<u64>(slotBytes + slotBytes / 2u, 4096u));
    BufferDesc d{};
    d.size = static_cast<usize>(stride * m_desc.framesInFlight);
    d.usage = ringUsage();
    d.memoryUsage = MemoryUsage::CpuToGpu;
    d.name = "light_tree.ring";
    Buffer fresh{};
    if (!m_desc.allocator->createBuffer(d, fresh) || fresh.mapped == nullptr || fresh.deviceAddress == 0u) {
        if (fresh.handle != nullptr) {
            m_desc.allocator->destroyBuffer(fresh);
        }
        return false;
    }
    if (m_ring.handle != nullptr) {
        m_retired.push_back(Retired{m_ring, m_frameSerial});
        ++m_stats.retired;
        ++m_stats.reallocations;
    }
    m_ring = fresh;
    m_ringQueue = rg::kNoQueue;
    m_slotStride = stride;
    for (u64& v : m_slotVersion) {
        v = 0u;
    }
    return true;
}

bool LightTreeGpu::beginFrame(u64 frameSerial, const LightTree& tree) {
    if (!m_initialized) {
        return false;
    }
    m_frameSerial = frameSerial;
    m_recordCount = 0;
    m_stats.passes = 0;
    const LightTreeView v = tree.view();
    const LightTreeSlotLayout layout = LightTreeSlotLayout::compute(v.nodeCount, v.emitterCount, v.directionalCount);
    if (!ensureCapacity(layout.bytes)) {
        return false;
    }
    m_slot = static_cast<u32>(frameSerial % m_desc.framesInFlight);
    const u64 base = static_cast<u64>(m_slot) * m_slotStride;
    u8* slot = static_cast<u8*>(m_ring.mapped) + base;
    const u64 address = m_ring.deviceAddress + base;
    if (m_slotVersion[m_slot] != tree.version()) {
        LightTreeHeader h{};
        h.nodes = address + layout.nodes;
        h.emitters = address + layout.emitters;
        h.directional = address + layout.directional;
        h.nodeCount = v.nodeCount;
        h.emitterCount = v.emitterCount;
        h.directionalCount = v.directionalCount;
        h.version = static_cast<u32>(tree.version());
        std::memcpy(slot + layout.header, &h, sizeof(h));
        const u64 nodeBytes = static_cast<u64>(v.nodeCount) * sizeof(LightTreeNode);
        const u64 emitterBytes = static_cast<u64>(v.emitterCount) * sizeof(LightTreeEmitter);
        const u64 dirBytes = static_cast<u64>(v.directionalCount) * sizeof(u32);
        if (nodeBytes != 0u) {
            std::memcpy(slot + layout.nodes, v.nodes, static_cast<usize>(nodeBytes));
        }
        if (emitterBytes != 0u) {
            std::memcpy(slot + layout.emitters, v.emitters, static_cast<usize>(emitterBytes));
        }
        if (dirBytes != 0u) {
            std::memcpy(slot + layout.directional, v.directional, static_cast<usize>(dirBytes));
        }
        m_slotVersion[m_slot] = tree.version();
        ++m_stats.uploads;
        m_stats.uploadBytes += sizeof(h) + nodeBytes + emitterBytes + dirBytes;
    }
    m_layout = layout;
    m_headerAddress = address + layout.header;
    return true;
}

LightTreeGraphRefs LightTreeGpu::importInto(rg::Graph& graph) {
    LightTreeGraphRefs refs{};
    if (!m_initialized || m_ring.handle == nullptr) {
        return refs;
    }
    refs.tree = graph.importBuffer(
        rg::ImportedBuffer{m_ring.handle, m_ring.desc.size, m_ringQueue, &m_ringQueue, "light_tree.ring"});
    refs.range = rg::BufferRange{static_cast<u64>(m_slot) * m_slotStride, m_slotStride};
    refs.header = m_headerAddress;
    return refs;
}

bool LightTreeGpu::addSamplePass(rg::Graph& graph, const LightTreeGraphRefs& refs, rg::BufferRef queries,
                                 u64 queriesOffset, u64 queriesAddress, rg::BufferRef results, u64 resultsOffset,
                                 u64 resultsAddress, u32 count) {
    if (!m_initialized || !refs.tree.valid() || !queries.valid() || !results.valid() || count == 0u ||
        queriesAddress == 0u || resultsAddress == 0u || m_recordCount >= kMaxPasses) {
        return false;
    }
    PassRecord& r = m_records[m_recordCount++];
    r = PassRecord{};
    r.self = this;
    r.push.header = refs.header;
    r.push.queries = queriesAddress;
    r.push.results = resultsAddress;
    r.push.count = count;
    r.groups = (count + kLtWorkgroup - 1u) / kLtWorkgroup;
    ++m_stats.passes;
    graph.addPass("light_tree.sample", &LightTreeGpu::recordDispatch, &r)
        .use(refs.tree, rg::Access::StorageRead, refs.range, rg::kStageCompute)
        .use(queries, rg::Access::StorageRead,
             rg::BufferRange{queriesOffset, static_cast<u64>(count) * sizeof(LightTreeQuery)}, rg::kStageCompute)
        .use(results, rg::Access::StorageWrite,
             rg::BufferRange{resultsOffset, static_cast<u64>(count) * sizeof(LightTreeSample)}, rg::kStageCompute);
    return true;
}

void LightTreeGpu::recordDispatch(const rg::PassContext& context, void* user) {
#if defined(FUSE_VULKAN_BACKEND)
    const PassRecord& r = *static_cast<const PassRecord*>(user);
    const LightTreeGpu& self = *r.self;
    VkCommandBuffer cmd = static_cast<VkCommandBuffer>(context.commandBuffer);
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, static_cast<VkPipeline>(self.m_pipeline));
    if (self.m_desc.bindless != nullptr) {
        self.m_desc.bindless->bind(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, self.m_layoutHandle, 0);
    }
    vkCmdPushConstants(cmd, static_cast<VkPipelineLayout>(self.m_layoutHandle), VK_SHADER_STAGE_COMPUTE_BIT, 0,
                       kPushBytes, &r.push);
    vkCmdDispatch(cmd, r.groups, 1u, 1u);
#else
    (void)context;
    (void)user;
#endif
}

u32 LightTreeGpu::collectRetired(u64 completedSerial) {
    u32 collected = 0;
    usize keep = 0;
    for (usize i = 0; i < m_retired.size(); ++i) {
        if (m_retired[i].serial > completedSerial) {
            m_retired[keep++] = m_retired[i];
            continue;
        }
        if (m_retired[i].buffer.handle != nullptr) {
            m_desc.allocator->destroyBuffer(m_retired[i].buffer);
        }
        ++collected;
    }
    m_retired.resize(keep);
    m_stats.retired = m_stats.retired >= collected ? m_stats.retired - collected : 0u;
    return collected;
}

} // namespace fuse::renderer::light_tree
